from pathlib import Path
from PIL import Image
import io,base64,json
root=Path(__file__).resolve().parent
rows=json.loads((root/'decisions.json').read_text())
def encode(path):
 im=Image.open(path).convert('RGB');im.thumbnail((290,406));b=io.BytesIO();im.save(b,'WEBP',quality=86)
 return 'data:image/webp;base64,'+base64.b64encode(b.getvalue()).decode()
for x in rows:
 for side in ['before','after']:x[side]=[encode(root/'rendered'/side/x['id']/f'court_{r}.webp')for r in 'jqk']
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Final court selections</title><style>*{box-sizing:border-box}body{margin:0;background:#201a15;color:#eee5d7;font:15px system-ui}main{max-width:1240px;margin:auto;padding:20px}h1{font:32px Georgia,serif}h2{font:26px Georgia,serif;margin:10px 0}p{color:#cdbca5;line-height:1.5}nav{position:sticky;top:0;background:#201a15f7;padding:12px 0;display:flex;gap:8px;flex-wrap:wrap}button,select{padding:10px 14px;background:#43301f;color:#fff0c8;border:1px solid #ad895a;border-radius:5px;cursor:pointer}.sets{display:grid;grid-template-columns:1fr 1fr;gap:20px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}img{width:100%;display:block}figure{margin:0}figcaption{color:#cdb592;padding:7px 0}section{padding:18px 0;border-top:1px solid #71593b}h3{font-size:16px;color:#e9c48d}small{color:#ddba82}@media(max-width:700px){.sets{grid-template-columns:1fr}main{padding:12px}}</style><main><small>INSTALLED SELECTIONS · NANO BANANA 2.1</small><h1>Final court selections</h1><p>21 object/creature sets installed. Zen Garden, Hangar X, The Velvet Moth, Arctic Station and Risograph Royalty retain their previous humanoid courts. Radio Outpost now has headphones / instrument panel / radio dish. Midnight Broadcast now has microphone / radio console / test-pattern TV.</p><nav><select id="theme" onchange="show(this.value)">OPTIONS</select><button onclick="show('approved')">21 object sets</button><button onclick="show('retained')">5 humanoid sets</button><button onclick="show('all')">All 26</button></nav><div id="gallery"></div></main><script>const rows=DATA;function show(id){document.getElementById('gallery').innerHTML=rows.filter(x=>id==='all'||x.id===id||x.status===id).map(x=>`<section><h2>${x.name}</h2><p>${x.status==='approved'?'New object / creature courts installed':'Previous humanoid courts retained'}</p><div class="sets">${['before','after'].map(side=>`<div><h3>${side==='before'?'Original set':'Installed selection'}</h3><div class="cards">${x[side].map((im,i)=>`<figure><img src="${im}" alt="${x.name} ${['Jack','Queen','King'][i]}"><figcaption>${['Jack','Queen','King'][i]}</figcaption></figure>`).join('')}</div></div>`).join('')}</div></section>`).join('');if(rows.some(x=>x.id===id))document.getElementById('theme').value=id}show('signal');</script></html>'''.replace('OPTIONS',''.join(f'<option value="{x["id"]}">{x["name"]}</option>'for x in rows)).replace('DATA',json.dumps(rows))
(root/'index.html').write_text(page)
print('Final selected-set preview:',len(page.encode()),'bytes')
